import { readFileSync } from 'node:fs';
const root = '<world>/state/worktrees/repo/';
const cases = [[2,3],[-2,3],[0,5],[-4,-6],[0,0]];
for (const n of ['add','mul','sub']) {
  const src = readFileSync(root + n + '/src/' + n + '.ts', 'utf8')
    .replace(/export function (\w+)\(a: number, b: number\): number/, 'function $1(a, b)');
  const f = new Function(src + '; return ' + n + ';')();
  console.log(n, cases.map(([a,b]) => `${n}(${a},${b})=${f(a,b)}`).join(' '));
}

